import * as ui from "std/ui"

@jsonable
class AppState {
  haircutDate: string;
  reminderLeadIndex: number;
}

function init(): AppState {
  return {haircutDate: "", reminderLeadIndex: 1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_haircutDate(state: AppState, value: string): AppState {
  return {haircutDate: value, reminderLeadIndex: state.reminderLeadIndex};
}

function set_reminderLead(state: AppState, value: number): AppState {
  return {reminderLeadIndex: value, haircutDate: state.haircutDate};
}







function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Next Haircut", "HAIRCUT REMINDER", "Set your next haircut and get a reminder", ""));
  {
      let reminderLeadValues: number[] = [0, 900, 3600, 86400];
      let reminderLead: number = reminderLeadValues[state.reminderLeadIndex];
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Next haircut", state.haircutDate, "set_haircutDate"), ui.Select("default", "Remind before", ["At the time", "15 min before", "1 hour before", "1 day before"], state.reminderLeadIndex, "set_reminderLead")]));
  }
  return ui.AppTheme("clean", "", sections);
}

