function c_cycleEnd(state: AppState): number {
  let minutesPerDay: number = 1440;
  let sleepMinutes: number = (((state.wakeBy - state.bedtime) + minutesPerDay) % minutesPerDay);
  let fullCycles: number = math.floor(share(sleepMinutes, state.cycleLength));
  return ((state.bedtime + (fullCycles * state.cycleLength)) % minutesPerDay);
}

function c_alarmTime(state: AppState): number {
  let cycleEnd: number = c_cycleEnd(state);
  let earliest: number = ((state.wakeBy - state.windowMinutes) + 1440) % 1440;
  if (cycleEnd > earliest) { return cycleEnd; }
  return earliest;
}

function c_setAlarm(state: AppState, ignored: number): AppState {
  sdk.call("SensorServiceKit.vibrator.vibrate", ["duration", "800"], "c_onAlarmAnswer");
  return {c_alarmPending: true, c_alarmStatus: "Setting alarm..."__PASSTHROUGH__};
}

function c_onAlarmAnswer(state: AppState, value: string): AppState {
  let failed: boolean = strings.startsWith(value, "declined") || strings.startsWith(value, "error");
  if (failed) {
    return {c_alarmPending: false, c_alarmStatus: "Could not set the alarm: " + value__PASSTHROUGH__};
  }
  return {c_alarmPending: false, c_alarmStatus: "Alarm set for " + ui.clockToString(c_alarmTime(state))__PASSTHROUGH__};
}
