import * as ui from "std/ui"

@jsonable
class AppState {
  reminderGapIndex: number;
  startTime: number;
  endTime: number;
}

function init(): AppState {
  return {reminderGapIndex: 2, startTime: 540, endTime: 1020};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_reminderGap(state: AppState, value: number): AppState {
  return {reminderGapIndex: value, startTime: state.startTime, endTime: state.endTime};
}

function set_startTime(state: AppState, value: number): AppState {
  return {startTime: value, reminderGapIndex: state.reminderGapIndex, endTime: state.endTime};
}

function set_endTime(state: AppState, value: number): AppState {
  return {endTime: value, reminderGapIndex: state.reminderGapIndex, startTime: state.startTime};
}







